import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.BvlN9b-o.js";const h=JSON.parse('{"title":"公开错误与排查","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/reference/errors","contentType":"reference","prev":false,"next":false},"headers":[],"relativePath":"reference/errors.md","filePath":"reference/errors.md"}'),d={name:"reference/errors.md"};function b(s,e,c,l,n,i){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="公开错误与排查" tabindex="-1">公开错误与排查 <a class="header-anchor" href="#公开错误与排查" aria-label="Permalink to &quot;公开错误与排查&quot;">​</a></h1><p>先用 HTTP 状态选择恢复动作，再用稳定 <code>error.code</code> 判断分支。错误结构由 <a href="./api#schema-ApiErrorResponse">ApiErrorResponse</a>和 <a href="./api#schema-ApiError">ApiError</a>生成；业务不要维护另一套 DTO。<code>error.message</code> 是公开说明，不是客户端分支键。当前 <code>public_error</code> 的 <code>details</code> 为空，不能假定包含数据库异常或表单字段。</p><h2 id="请求关联" tabindex="-1">请求关联 <a class="header-anchor" href="#请求关联" aria-label="Permalink to &quot;请求关联&quot;">​</a></h2><p>Core <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/http.rs" target="_blank" rel="noreferrer">request_context</a>为每个请求生成新 <code>RequestId</code>，返回 <code>x-request-id</code>；错误 JSON 的 <code>error.request_id</code> 使用相同值。不会直接信任客户端传入的 request id。对错误记录方法、路由、状态、稳定码和 request_id，再在 日志与追踪中定位；不要记录 Cookie、Authorization、请求正文或签名 URL。</p><p>在运行本地 API 后观察一个安全的失败请求：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:18000/api/v1/does-not-exist</span></span></code></pre></div><p>结果应为 <code>404</code>、<code>http.not_found</code>，带 <code>x-request-id</code> 和匹配的 JSON request_id。如果收到 HTML 或代理错误，先检查代理目标和路径；该响应尚未经过 Core 错误边界。</p><h2 id="http-与认证" tabindex="-1">HTTP 与认证 <a class="header-anchor" href="#http-与认证" aria-label="Permalink to &quot;HTTP 与认证&quot;">​</a></h2><table tabindex="0"><thead><tr><th>状态</th><th>稳定码 / 来源</th><th>恢复动作</th></tr></thead><tbody><tr><td>400</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/http.rs" target="_blank" rel="noreferrer"><code>http.invalid_json</code></a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/http.rs" target="_blank" rel="noreferrer"><code>http.invalid_query</code></a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/http.rs" target="_blank" rel="noreferrer"><code>http.invalid_path</code></a></td><td>修正 JSON、query 或路径类型；不要原样重试</td></tr><tr><td>404 / 405</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/http.rs" target="_blank" rel="noreferrer"><code>http.not_found</code></a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/http.rs" target="_blank" rel="noreferrer"><code>http.method_not_allowed</code></a></td><td>检查 API 组装、路径和 HTTP 方法，对照当前 OpenAPI</td></tr><tr><td>408 / 413</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/http.rs" target="_blank" rel="noreferrer"><code>http.body_timeout</code></a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/http.rs" target="_blank" rel="noreferrer"><code>http.payload_too_large</code></a></td><td>检查上传速度或减少请求体；文件走 Files 协议，不扩大普通 JSON 预算</td></tr><tr><td>401</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/identity/mod.rs" target="_blank" rel="noreferrer"><code>auth.unauthorized</code></a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/identity/mod.rs" target="_blank" rel="noreferrer"><code>auth.invalid_credentials</code></a></td><td>重新登录或使用有效凭据；Bearer 不会退回 Cookie</td></tr><tr><td>403</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/identity/mod.rs" target="_blank" rel="noreferrer"><code>auth.origin</code></a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/identity/mod.rs" target="_blank" rel="noreferrer"><code>auth.csrf</code></a></td><td>核对 APP_ORIGIN；刷新 Session，使用当前 csrf_token 发起 mutation</td></tr><tr><td>403</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/api_keys/authentication.rs" target="_blank" rel="noreferrer"><code>api_keys.scope_forbidden</code></a></td><td>申请需要的 scope；资源访问仍由业务规则检查</td></tr><tr><td>409</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/identity/mod.rs" target="_blank" rel="noreferrer"><code>auth.email_exists</code></a></td><td>使用现有账号或选择其他注册邮箱</td></tr><tr><td>429</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/http.rs" target="_blank" rel="noreferrer"><code>rate_limit.exceeded</code></a></td><td>遵循 <code>Retry-After</code>，有界退避；不要持续并发重试</td></tr><tr><td>503</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/lib.rs" target="_blank" rel="noreferrer"><code>database.unavailable</code></a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/identity/mod.rs" target="_blank" rel="noreferrer"><code>auth.unavailable</code></a></td><td>检查数据库、迁移与连接预算；保留 request_id 供排查，有界重试</td></tr><tr><td>503</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/identity/mod.rs" target="_blank" rel="noreferrer"><code>auth.session_unavailable</code></a></td><td>账号事务可能已提交但 Session 创建失败；改用登录，不重复注册</td></tr></tbody></table><h2 id="files-与任务" tabindex="-1">Files 与任务 <a class="header-anchor" href="#files-与任务" aria-label="Permalink to &quot;Files 与任务&quot;">​</a></h2><table tabindex="0"><thead><tr><th>状态</th><th>稳定码 / 来源</th><th>恢复动作</th></tr></thead><tbody><tr><td>400 / 413</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/files/mod.rs" target="_blank" rel="noreferrer"><code>files.invalid_input</code></a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/files/mod.rs" target="_blank" rel="noreferrer"><code>files.too_large</code></a></td><td>修正文件名、媒体类型、字节数或 SHA-256；限制来自生成配置</td></tr><tr><td>404 / 410</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/files/mod.rs" target="_blank" rel="noreferrer"><code>files.not_found</code></a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/files/mod.rs" target="_blank" rel="noreferrer"><code>files.upload_expired</code></a></td><td>前者核对业务归属；后者创建新上传会话</td></tr><tr><td>409</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/files/mod.rs" target="_blank" rel="noreferrer"><code>files.upload_missing</code></a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/files/mod.rs" target="_blank" rel="noreferrer"><code>files.upload_changed</code></a></td><td>先上传实际字节；内容变化时重新核验完成流程</td></tr><tr><td>422</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/files/mod.rs" target="_blank" rel="noreferrer"><code>files.upload_rejected</code></a></td><td>创建新上传会话并重新计算大小/摘要</td></tr><tr><td>503</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/files/mod.rs" target="_blank" rel="noreferrer"><code>files.unavailable</code></a></td><td>核对 API 与 Worker 存储配置、bucket 和对象服务；只做有界重试</td></tr></tbody></table><p>任务错误不是一张 HTTP 状态表。Handler 返回 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/jobs/mod.rs" target="_blank" rel="noreferrer">JobError</a>：<code>Permanent</code> 结束当前批次，<code>Transient</code> 按预算重试，<code>LostLease</code> 停止发布。Job 详情与尝试记录提供 last_error；恢复指南说明何时由管理员开始新批次。排查时同时保留 job_id、correlation_id 与最初 request_id。</p><h2 id="自己的业务错误" tabindex="-1">自己的业务错误 <a class="header-anchor" href="#自己的业务错误" aria-label="Permalink to &quot;自己的业务错误&quot;">​</a></h2><p>Domain 先定义自己的失败类型，HTTP 边界通过 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/http.rs" target="_blank" rel="noreferrer"><code>public_error</code></a>映射到状态和带业务前缀的稳定码。事务内部失败必须回滚；幂等键内容冲突与旧版本写入应返回 <code>409</code>，不得静默覆盖或以成功响应掩盖失败。每个分支写至少一个公开失败行为检查，见 <a href="./../testing/feedback-loop">测试反馈循环</a>。</p><p>服务启动前的 <code>ConfigError</code> 不会产生 HTTP 响应；按错误指向的变量检查 <a href="./configuration-sources">配置来源</a>。API 就绪失败时先验证迁移，Worker 不领取时先核对 kind 注册与运行状态，再检查租约和任务预算。</p><p>参考业务的 <a href="./../tutorials/observability">日志与追踪指南</a>和 <a href="./../tutorials/job-recovery">任务恢复指南</a>提供完整请求/任务排查流程；移除知识库后保留 Core 错误参考和公共源码入口。</p><hr><p>源码版本：<code>261be5bb90df</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/docs/reference/errors.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>',18)])])}const u=a(d,[["render",b]]);export{h as __pageData,u as default};
